/*
System:   renderEntities            Phase: frame
Job:      Draw the game objects' sprites at their interpolated positions, wrap-aware
          (Design §10.1, §10.3.3, Impl §4.3, §5.4). So far: the ship and its exhaust flame.
Reads:    world.ship, world.phase, world.camera, fx.shake, time.alpha, time.now
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    world exists
*/
import { BLINK_TICKS, FLAME, HUD_HEIGHT } from '../../config/constants';
import { lerp } from '../../core/math';
import type { Display } from '../../host/display';
import type { SpriteAtlas } from '../../host/sprites';
import { cameraXAt, flameWidth, isDrawable, lerpX, screenX } from '../../model/queries';
import type { World } from '../../model/state/world';
import type { System } from '../../scheduler/system';

/** The ship is hidden in hyperspace and while dying, and blinks while invulnerable (Design §10.1). */
function shipVisible(world: World): boolean {
  const { ship } = world;
  if (ship.hyperspaceTicks > 0 || world.phase === 'playerDying') return false;
  return Math.floor(ship.invulnerableTicks / BLINK_TICKS) % 2 === 0;
}

export function createRenderEntities(): System {
  let display: Display | null = null;
  let sprites: SpriteAtlas | null = null;

  return {
    name: 'renderEntities',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
      sprites = host.sprites;
    },
    update(state) {
      const { world } = state;
      if (!display || !sprites || !world) return;
      const ctx = display.scene;
      const { alpha } = state.time;
      const cam = cameraXAt(world, alpha);
      ctx.save();
      ctx.translate(state.fx.shake.x, state.fx.shake.y);

      const { ship } = world;
      const x = screenX(cam, lerpX(ship.prevX, ship.x, alpha));
      const y = HUD_HEIGHT + lerp(ship.prevY, ship.y, alpha);
      if (shipVisible(world) && isDrawable(x)) {
        const flipX = ship.facing === -1;
        if (ship.thrusting) {
          const width = flameWidth(state.time.now);
          const flameX = x + ship.facing * (FLAME.offsetX - width / 2);
          sprites.draw(ctx, 'shipFlame', 0, flameX, y + FLAME.offsetY, {
            width,
            height: FLAME.height,
            flipX,
          });
        }
        sprites.draw(ctx, 'ship', 0, x, y, { flipX });
      }
      ctx.restore();
    },
    dispose() {
      display = null;
      sprites = null;
    },
  };
}
