import { CAMERA, NEW_GAME, TERRAIN, TERRAIN_SEED } from '../config/constants';
import { clamp, wrapX } from '../core/math';
import { random } from '../core/random';
import type { Ship } from './state/entities';
import type { GameState } from './state/gameState';
import type { Difficulty } from './state/settings';
import type { World } from './state/world';

export interface NewWorldOptions {
  seed: number;
  difficulty: Difficulty;
  demo: boolean;
  /** The wave to start on. */
  startWave: number;
}

/**
 * Creates the world of a new game and reseeds `rng` with its seed (Design §4.3, Impl §4.1).
 * The ship starts at (0, 400) facing right, and the camera anchor at 480. Entities and the wave
 * start (Design §7.2) arrive with later milestones.
 */
export function newWorld(state: GameState, options: NewWorldOptions): World {
  const { seed, difficulty, demo, startWave } = options;
  const ship = createShip(1, NEW_GAME.shipX, NEW_GAME.shipY);
  const anchor = CAMERA.anchorFacingRight;
  const cameraX = wrapX(ship.x - anchor);
  const world: World = {
    seed,
    difficulty,
    demo,
    tick: 0,
    // As the wave start does, so the first tick is the first active one (Impl §4.2).
    activeFrom: 1,
    phase: 'active',
    phaseTicks: 0,
    wave: startWave,
    waveTick: 0,
    landersPending: 0,
    nextGroupTick: 0,
    baiterNextTick: 0,
    bomberDir: 1,
    speedMult: 1,
    fireIntervalMult: 1,
    bulletSpeedMult: 1,
    score: 0,
    ships: NEW_GAME.ships,
    bombs: NEW_GAME.bombs,
    nextBonusAt: NEW_GAME.bonusInterval,
    planetAlive: true,
    camera: { x: cameraX, prevX: cameraX, anchor },
    ship,
    humanoids: [],
    enemies: [],
    lasers: [],
    bullets: [],
    mines: [],
    terrain: generateTerrain(),
    nextId: ship.id + 1,
    laserColorCounter: 0,
    lastWaveResult: null,
    godMode: false,
  };
  state.rng = { s: seed >>> 0 };
  state.world = world;
  return world;
}

/** A ship at rest, facing right (Design §4.3). */
function createShip(id: number, x: number, y: number): Ship {
  return {
    id,
    x,
    y,
    prevX: x,
    prevY: y,
    vx: 0,
    vy: 0,
    dead: false,
    facing: 1,
    thrusting: false,
    fireCooldown: 0,
    autoFireTicks: 0,
    smartBombCooldown: 0,
    hyperspaceTicks: 0,
    hyperspaceCooldown: 0,
    invulnerableTicks: 0,
    carryingId: null,
    autopilotLastReverse: -1,
  };
}

/**
 * The terrain heights: circular midpoint displacement from the fixed terrain seed, so it is the
 * same in every game (Design §4.6). Uses its own generator; the game `rng` is untouched (Impl §4.1).
 */
export function generateTerrain(): Float32Array {
  const n: number = TERRAIN.vertices;
  const h = new Float32Array(n);
  const rng = { s: TERRAIN_SEED };
  h[0] = TERRAIN.start;
  let d = TERRAIN.displacement;
  for (let step = n; step >= 2; step /= 2) {
    for (let i = 0; i < n; i += step) {
      const a = h[i] ?? 0;
      const b = h[(i + step) % n] ?? 0;
      h[i + step / 2] = clamp((a + b) / 2 + random(rng, -d, d), TERRAIN.min, TERRAIN.max);
    }
    d *= TERRAIN.decay;
  }
  return h;
}

/** The camera anchor the ship's facing aims for (Design §4.5). */
export function cameraTarget(ship: Ship): number {
  return ship.facing === 1 ? CAMERA.anchorFacingRight : CAMERA.anchorFacingLeft;
}

/**
 * Snaps the camera anchor to its target, with no interpolation from the old view. Used on respawn
 * and on hyperspace arrival (Design §4.5).
 */
export function snapCamera(world: World): void {
  const { camera, ship } = world;
  camera.anchor = cameraTarget(ship);
  camera.x = wrapX(ship.x - camera.anchor);
  camera.prevX = camera.x;
}
