/** Mulberry32 generator state, the shape of the state's `rng` slice (Code §2.5). */
interface Mulberry32State {
  s: number;
}

/** Advances `r.s` and returns a value in [0, 1). */
export function next(r: Mulberry32State): number {
  r.s = (r.s + 0x6d2b79f5) >>> 0;
  let t = r.s;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

/** Uniform real in [a, b) (Design §2). */
export const random = (r: Mulberry32State, a: number, b: number) => a + (b - a) * next(r);

/** Uniform integer in [a, b], inclusive (Design §2). */
export const randomInt = (r: Mulberry32State, a: number, b: number) =>
  Math.floor(random(r, a, b + 1));

/** True with probability p (Design §2). */
export const chance = (r: Mulberry32State, p: number) => next(r) < p;

/** +1 or −1 with equal probability (Design §2). */
export const randomSign = (r: Mulberry32State): 1 | -1 => (next(r) < 0.5 ? 1 : -1);
