/**
 * The JSON codec for state (Code §9.1). Typed arrays, maps, and sets are written as tagged
 * objects, and `decode(encode(s))` deep-equals `s`.
 */

const TYPED_ARRAYS = { Float32Array, Int32Array, Uint8Array } as const;

type TypedArrayName = keyof typeof TYPED_ARRAYS;

/** Converts a state value (or the whole state) to JSON. `space` pretty-prints, as `JSON.stringify`. */
export function encode(value: unknown, space?: number): string {
  return JSON.stringify(value, (_key, v: unknown) => tag(v), space);
}

/** Converts JSON from `encode` back to a state value. Throws on an unknown or malformed tag. */
export function decode(text: string): unknown {
  return JSON.parse(text, (_key, v: unknown) => untag(v));
}

function tag(v: unknown): unknown {
  for (const name of Object.keys(TYPED_ARRAYS) as TypedArrayName[]) {
    if (v instanceof TYPED_ARRAYS[name]) return { $type: name, data: Array.from(v) };
  }
  if (v instanceof Map) return { $type: 'Map', entries: [...v.entries()] };
  if (v instanceof Set) return { $type: 'Set', values: [...v] };
  return v;
}

function untag(v: unknown): unknown {
  if (typeof v !== 'object' || v === null || !('$type' in v)) return v;
  const tagged = v as Record<string, unknown>;
  const type = tagged.$type;
  switch (type) {
    case 'Float32Array':
    case 'Int32Array':
    case 'Uint8Array':
      return new TYPED_ARRAYS[type](numbers(tagged.data, type));
    case 'Map':
      return new Map(list(tagged.entries, type).map((entry) => pair(entry)));
    case 'Set':
      return new Set(list(tagged.values, type));
    default:
      throw new Error(`json: unknown $type ${JSON.stringify(type)}`);
  }
}

function list(value: unknown, type: string): unknown[] {
  if (!Array.isArray(value)) throw new Error(`json: malformed ${type}`);
  return value as unknown[];
}

function numbers(value: unknown, type: string): number[] {
  const items = list(value, type);
  if (!items.every((item) => typeof item === 'number')) throw new Error(`json: malformed ${type}`);
  return items;
}

function pair(entry: unknown): [unknown, unknown] {
  const items = list(entry, 'Map entry');
  if (items.length !== 2) throw new Error('json: malformed Map entry');
  return [items[0], items[1]];
}
