/*
System:   renderBackdrop            Phase: frame
Job:      Draw the backdrop across the playfield band, scrolling at a quarter of the camera speed
          (Design §10.4, Impl §5.4). Not shaken.
Reads:    world.camera, app.screen, app.attractPage, time.alpha, time.now
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    world exists, or the attract title page is shown
*/
import { BACKDROP, HUD_HEIGHT, PLAYFIELD_HEIGHT, SCREEN_W } from '../../config/constants';
import type { Display } from '../../host/display';
import type { SpriteAtlas } from '../../host/sprites';
import { backgroundCameraX } from '../../model/queries';
import type { System } from '../../scheduler/system';

const CENTER_Y = HUD_HEIGHT + PLAYFIELD_HEIGHT / 2;

export function createRenderBackdrop(): System {
  let display: Display | null = null;
  let sprites: SpriteAtlas | null = null;

  return {
    name: 'renderBackdrop',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
      sprites = host.sprites;
    },
    update(state) {
      const cam = backgroundCameraX(state);
      if (!display || !sprites || cam === null) return;
      // W × 0.25 = 2 × 1920, so two copies wrap seamlessly.
      const left = -((cam * BACKDROP.parallax) % SCREEN_W);
      sprites.draw(display.scene, 'backdrop', 0, left + SCREEN_W / 2, CENTER_Y);
      sprites.draw(display.scene, 'backdrop', 0, left + (SCREEN_W * 3) / 2, CENTER_Y);
    },
    dispose() {
      display = null;
      sprites = null;
    },
  };
}
