/*
System:   renderTerrain             Phase: frame
Job:      Draw the terrain: the textured fill below the terrain line, and the ridge on top
          (Design §10.4, Impl §5.4).
Reads:    world.terrain, world.planetAlive, world.camera, fx.shake, time.alpha
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    world exists and the planet is alive
*/
import {
  HUD_HEIGHT,
  PLAYFIELD_HEIGHT,
  SCREEN_W,
  TERRAIN,
  TERRAIN_FILL,
} from '../../config/constants';
import { PALETTE } from '../../config/palette';
import { SPRITES } from '../../config/sprites';
import type { Display } from '../../host/display';
import type { SpriteAtlas } from '../../host/sprites';
import { cameraXAt } from '../../model/queries';
import type { System } from '../../scheduler/system';

const BOTTOM = HUD_HEIGHT + PLAYFIELD_HEIGHT;
const TILE = SPRITES.terrain;

export function createRenderTerrain(): System {
  let display: Display | null = null;
  let sprites: SpriteAtlas | null = null;

  return {
    name: 'renderTerrain',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
      sprites = host.sprites;
    },
    update(state) {
      const { world } = state;
      if (!display || !sprites || !world?.planetAlive) return;
      const ctx = display.scene;
      const cam = cameraXAt(world, state.time.alpha);
      const { spacing, vertices } = TERRAIN;

      // The vertices with screen x in [−60, 1980], plus one more on each side (Impl §5.4).
      const first = Math.floor((cam - spacing) / spacing) - 1;
      const last = Math.ceil((cam + SCREEN_W + spacing) / spacing) + 1;
      const ridge = (path: CanvasRenderingContext2D) => {
        for (let k = first; k <= last; k++) {
          const h = world.terrain[((k % vertices) + vertices) % vertices] ?? TERRAIN.start;
          const x = k * spacing - cam;
          if (k === first) path.moveTo(x, HUD_HEIGHT + h);
          else path.lineTo(x, HUD_HEIGHT + h);
        }
      };

      ctx.save();
      ctx.translate(state.fx.shake.x, state.fx.shake.y);
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';

      // Fill: the terrain texture, clipped to the area below the terrain line.
      ctx.save();
      ctx.beginPath();
      ridge(ctx);
      ctx.lineTo(last * spacing - cam, BOTTOM);
      ctx.lineTo(first * spacing - cam, BOTTOM);
      ctx.closePath();
      ctx.clip();
      const offset = -(cam % TERRAIN_FILL.tileWidth);
      const centerY = HUD_HEIGHT + TERRAIN_FILL.top + TILE.h / 2;
      // k = −1…4: the extra tile covers the shake offset.
      for (let k = -1; k <= 4; k++)
        sprites.draw(ctx, 'terrain', 0, offset + k * TERRAIN_FILL.tileWidth + TILE.w / 2, centerY);
      ctx.restore();

      // Ridge.
      ctx.beginPath();
      ridge(ctx);
      ctx.strokeStyle = PALETTE.terrain;
      ctx.lineWidth = TERRAIN_FILL.ridgeWidth;
      ctx.stroke();
      ctx.restore();
    },
    dispose() {
      display = null;
      sprites = null;
    },
  };
}
