import { ATTRACT_SCROLL_SPEED, FLAME, SCREEN_W } from '../config/constants';
import { HITBOXES, SPRITES, type HitboxSprite } from '../config/sprites';
import { fnv1a } from '../core/hash';
import { WORLD_WIDTH, wrapDelta, wrapX } from '../core/math';
import { next } from '../core/random';
import { encode } from './json';
import type { GameEvent } from './state/events';
import type { GameState } from './state/gameState';
import type { World } from './state/world';

/** A state whose world exists. */
export type WithWorld = GameState & { world: World };

/** The events produced so far in the current tick: the only ones a tick system reads (Code §3.3). */
export function eventsThisTick(state: GameState): GameEvent[] {
  return state.events.filter((event) => event.tick === state.time.tick);
}

/** The world is being simulated: a game is playing, or the attract demo runs (Impl §4.2). */
export function simRunning(state: GameState): state is WithWorld {
  const { world, app } = state;
  return world !== null && (app.screen === 'playing' || (app.screen === 'attract' && world.demo));
}

/** Gameplay acts this tick: the world runs, its phase is `active`, and it's past `activeFrom` (Impl §4.2). */
export function simActive(state: GameState): state is WithWorld {
  return (
    simRunning(state) &&
    state.world.phase === 'active' &&
    state.world.tick >= state.world.activeFrom
  );
}

/** World x is on-screen: `wrapX(x − cameraX) < 1920` (Design §2, §4.5). */
export function isOnScreen(world: World, x: number): boolean {
  return wrapX(x - world.camera.x) < SCREEN_W;
}

/** The interpolated x between two ticks, wrap-aware (Impl §4.3). */
export function lerpX(prevX: number, x: number, alpha: number): number {
  return wrapX(prevX + wrapDelta(prevX, x) * alpha);
}

/** The interpolated camera x (Impl §4.3). */
export function cameraXAt(world: World, alpha: number): number {
  return lerpX(world.camera.prevX, world.camera.x, alpha);
}

/**
 * The camera x behind the backdrop and stars: the world's, or on the attract title page (no world)
 * a scroll at 200 px/s (Design §8.3, Impl §5.3). Null when those layers aren't drawn.
 */
export function backgroundCameraX(state: GameState): number | null {
  if (state.world) return cameraXAt(state.world, state.time.alpha);
  if (state.app.screen === 'attract' && state.app.attractPage === 'title')
    return wrapX(state.time.now * ATTRACT_SCROLL_SPEED);
  return null;
}

/** The screen x of world x for a camera at `cameraX`, wrap-aware (Impl §5.4). */
export function screenX(cameraX: number, x: number): number {
  const sx = wrapDelta(cameraX, x);
  return sx < -200 ? sx + WORLD_WIDTH : sx;
}

/** Whether a screen x is close enough to the visible area to draw (Design §10.1, Impl §5.4). */
export function isDrawable(sx: number): boolean {
  return sx >= -100 && sx <= SCREEN_W + 100;
}

/** An object's hitbox: its center and size (Design §2). */
export interface Hitbox {
  cx: number;
  cy: number;
  w: number;
  h: number;
}

/**
 * The hitbox of an object drawn with `sprite` centered on (x, y), mirrored with the sprite when
 * `flipX` (Design §2, Impl §5.9).
 */
export function hitboxAt(sprite: HitboxSprite, x: number, y: number, flipX: boolean): Hitbox {
  const frame = SPRITES[sprite];
  const box = HITBOXES[sprite];
  const left = flipX ? x + frame.w / 2 - box.x - box.w : x - frame.w / 2 + box.x;
  return { cx: left + box.w / 2, cy: y - frame.h / 2 + box.y + box.h / 2, w: box.w, h: box.h };
}

/**
 * The exhaust flame's length at real time `now` (seconds): a new random length 30 times a second
 * (Design §10.3.3). Visual only, so it never touches `rng`: each 1/30 s slot seeds its own value.
 */
export function flameWidth(now: number): number {
  const slot = { s: Math.floor(now * FLAME.rollsPerSecond) >>> 0 };
  return FLAME.minWidth + next(slot) * (FLAME.maxWidth - FLAME.minWidth);
}

/** FNV-1a over the world's JSON, for the debug overlay and determinism checks (Impl §4.6). */
export function hashWorld(world: World): string {
  return fnv1a(encode(world));
}
