import { ACTIONS, DEFAULT_KEY_BINDINGS } from '../config/keys';
import type { GameState } from './state/gameState';
import type { HighScoreEntry, HighScoreStore } from './state/highScores';
import type { TickInput } from './state/input';
import type { KeyBindings, Settings } from './state/settings';

/** The default high-score initials, best first (Design §12.3). */
const DEFAULT_INITIALS = ['NEO', 'VEC', 'LSR', 'BOM', 'HYP', 'MUT', 'LND', 'POD', 'SWM', 'BTR'];

/** The state at program start: screen `boot`, no world, settings and high scores at defaults. */
export function createInitialState(): GameState {
  return {
    app: {
      screen: 'boot',
      returnTo: null,
      menuIndex: 0,
      screenTime: 0,
      attractPage: 'title',
      highScoreView: { difficulty: 'normal', highlightIndex: null },
      initials: { chars: [0, 0, 0], cursor: 0, score: 0, wave: 0, difficulty: 'normal' },
      rebind: null,
      message: null,
      platform: {
        touchPrimary: false,
        touchSeen: false,
        portrait: false,
        hidden: false,
        fullscreenRequested: false,
        cursorHidden: false,
        fontReady: false,
        spritesReady: false,
      },
      dev: {
        overlay: false,
        godMode: false,
        gallery: false,
        inspectorSlice: null,
        replay: { mode: 'off', initial: null, frames: [], index: 0 },
      },
    },
    settings: createDefaultSettings(),
    highScores: createDefaultHighScores(),
    input: {
      devices: {
        keyboard: { down: new Set(), pressed: [] },
        gamepad: {
          connected: false,
          lostThisFrame: false,
          down: new Set(),
          pressed: [],
          stickX: 0,
          stickY: 0,
          rt: 0,
        },
        pointer: { stick: null, buttonsDown: new Set(), buttonsPressed: [], tap: null },
      },
      held: { vertical: 0, horizontal: 0, thrust: false, fire: false },
      latched: { reverse: false, fire: false, smartBomb: false, hyperspace: false },
      tick: createTickInput(),
      menu: {
        up: false,
        down: false,
        left: false,
        right: false,
        confirm: false,
        back: false,
        tap: null,
        typed: [],
        deletePressed: false,
        anyKeyCode: null,
      },
      frame: { pause: false, mute: false, start: false },
      repeat: { dir: null, heldTime: 0, nextAt: 0 },
    },
    time: { tick: 0, now: 0, frameDt: 0, alpha: 0 },
    rng: { s: 0 },
    world: null,
    fx: {
      shake: { amplitude: 0, duration: 0, elapsed: 0, x: 0, y: 0 },
      flash: { color: '#FFFFFF', alpha: 0, duration: 0, elapsed: 0, pulses: 0 },
      rings: [],
    },
    events: [],
  };
}

/** A player intent with nothing pressed. */
function createTickInput(): TickInput {
  return {
    vertical: 0,
    thrust: false,
    reverse: false,
    fire: false,
    fireHeld: false,
    smartBomb: false,
    hyperspace: false,
  };
}

/** The default settings (Design §12.2). */
function createDefaultSettings(): Settings {
  return {
    version: 1,
    masterVolume: 80,
    sfxVolume: 80,
    musicVolume: 50,
    muted: false,
    glow: 'high',
    reduceMotion: false,
    touchControls: 'auto',
    keyBindings: createDefaultKeyBindings(),
    lastDifficulty: 'normal',
  };
}

/** A fresh copy of the default bindings (Design §9.1). */
function createDefaultKeyBindings(): KeyBindings {
  return Object.fromEntries(
    ACTIONS.map((action) => {
      const [slot1, slot2] = DEFAULT_KEY_BINDINGS[action];
      return [action, [slot1, slot2]];
    }),
  ) as KeyBindings;
}

/** The default tables, the same for each difficulty (Design §12.3). */
function createDefaultHighScores(): HighScoreStore {
  const table = (): HighScoreEntry[] =>
    DEFAULT_INITIALS.map((initials, i) => ({
      initials,
      score: 10000 - i * 1000,
      wave: 1,
      date: '2026-01-01',
    }));
  return { version: 1, tables: { easy: table(), normal: table(), hard: table() } };
}
