/** World width W in px (Design §2, §3.2). */
export const WORLD_WIDTH = 15360;

const W = WORLD_WIDTH;

/** x wrapped into [0, W) (Design §2). */
export function wrapX(x: number): number {
  return ((x % W) + W) % W;
}

/** Signed shortest horizontal distance from `from` to `to` around the world, in [−W/2, W/2) (Design §2). */
export function wrapDelta(from: number, to: number): number {
  const d = wrapX(to - from);
  return d >= W / 2 ? d - W : d;
}

/** Centered hitbox overlap with strict inequalities, wrap-aware in x (Design §2). */
export function aabbOverlap(
  ax: number,
  ay: number,
  aw: number,
  ah: number,
  bx: number,
  by: number,
  bw: number,
  bh: number,
): boolean {
  return Math.abs(wrapDelta(ax, bx)) < (aw + bw) / 2 && Math.abs(ay - by) < (ah + bh) / 2;
}

/** v limited to [lo, hi] (Design §2). */
export function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** −1, 0, or +1 (Design §2). */
export function sign(x: number): -1 | 0 | 1 {
  return x > 0 ? 1 : x < 0 ? -1 : 0;
}
