/*
System:   cheats                    Phase: frame
Job:      Apply the developer keys (Impl §10).
Reads:    input.devices.keyboard.pressed, app.dev.overlay, app.dev.gallery
Writes:   app.dev.overlay, app.dev.gallery
Emits:    —
Consumes: —
Guard:    a developer key was pressed this frame
*/
import type { System } from '../../scheduler/system';

export function createCheats(): System {
  return {
    name: 'cheats',
    phase: 'frame',
    init() {
      // No platform resources.
    },
    update(state) {
      const { pressed } = state.input.devices.keyboard;
      if (pressed.length === 0) return;
      if (pressed.includes('F3')) state.app.dev.overlay = !state.app.dev.overlay;
      if (pressed.includes('F9')) state.app.dev.gallery = !state.app.dev.gallery;
    },
    dispose() {
      // Nothing to release.
    },
  };
}
