import type { GameState } from '../model/state/gameState';
import { createDisplay, type Display } from './display';
import { createBrowserPlatform, type Platform } from './platform';
import { createSpriteAtlas, type SpriteAtlas } from './sprites';

/** The key-event source: `window` in the browser. */
export type KeyEventTarget = Pick<Window, 'addEventListener' | 'removeEventListener'>;

/** Device input sources (Impl §3.4). */
export interface InputSources {
  window: KeyEventTarget;
}

/** The bridge to the platform (Code §6, Impl §3.4). Systems receive it only in `init`. */
export interface Host {
  display: Display;
  sprites: SpriteAtlas;
  inputs: InputSources;
  platform: Platform;
  /** Seconds (`performance.now() / 1000`). */
  clock: { now(): number };
  log: { warn(msg: string): void; error(msg: string, err: unknown): void };
  /** Set by the scheduler when it's created (Code §6). Only dev tooling systems use it. */
  control: { replaceState(next: GameState): void; stop(): void };
}

export function createBrowserHost(canvas: HTMLCanvasElement): Host {
  // The page never shows a context menu (Design §3.3).
  canvas.addEventListener('contextmenu', (e) => {
    e.preventDefault();
  });
  return {
    display: createDisplay(canvas),
    sprites: createSpriteAtlas(),
    inputs: { window },
    platform: createBrowserPlatform(),
    clock: { now: () => performance.now() / 1000 },
    log: {
      warn: (msg) => {
        console.warn(msg);
      },
      error: (msg, err) => {
        console.error(msg, err);
      },
    },
    control: {
      replaceState: () => {
        throw new Error('host: no scheduler attached');
      },
      stop: () => {
        throw new Error('host: no scheduler attached');
      },
    },
  };
}
