/*
System:   worldClock                Phase: tick
Job:      Advance the world's tick and remember last tick's positions for interpolation
          (Code §2.5, Impl §4.3).
Reads:    world
Writes:   world.tick, world.camera.prevX, prevX/prevY of world.ship, humanoids, enemies, lasers,
          bullets, mines
Emits:    —
Consumes: —
Guard:    simRunning
*/
import { simRunning } from '../../model/queries';
import type { EntityBase } from '../../model/state/entities';
import type { System } from '../../scheduler/system';

function keepPrev(entity: EntityBase) {
  entity.prevX = entity.x;
  entity.prevY = entity.y;
}

export function createWorldClock(): System {
  return {
    name: 'worldClock',
    phase: 'tick',
    init() {
      // No platform resources.
    },
    update(state) {
      if (!simRunning(state)) return;
      const { world } = state;
      world.tick += 1;
      world.camera.prevX = world.camera.x;
      keepPrev(world.ship);
      world.humanoids.forEach(keepPrev);
      world.enemies.forEach(keepPrev);
      world.lasers.forEach(keepPrev);
      world.bullets.forEach(keepPrev);
      world.mines.forEach(keepPrev);
    },
    dispose() {
      // Nothing to release.
    },
  };
}
