import backdropUrl from '../../assets/sprites/Backdrop.png';
import baiterUrl from '../../assets/sprites/Baiter.png';
import bomberUrl from '../../assets/sprites/Bomber.png';
import bulletUrl from '../../assets/sprites/Bullet.png';
import humanoidUrl from '../../assets/sprites/Humanoid.png';
import landerUrl from '../../assets/sprites/Lander.png';
import laserUrl from '../../assets/sprites/Laser.png';
import mineUrl from '../../assets/sprites/Mine.png';
import mutantUrl from '../../assets/sprites/Mutant.png';
import podUrl from '../../assets/sprites/Pod.png';
import shipUrl from '../../assets/sprites/Ship.png';
import shipFlameUrl from '../../assets/sprites/ShipFlame.png';
import swarmerUrl from '../../assets/sprites/Swarmer.png';
import terrainUrl from '../../assets/sprites/Terrain.png';
import { SPRITES, type SpriteName } from '../config/sprites';

/** The art files, imported statically so a missing one fails the build (Impl §5.9). */
const URLS: Record<SpriteName, string> = {
  ship: shipUrl,
  shipFlame: shipFlameUrl,
  lander: landerUrl,
  mutant: mutantUrl,
  bomber: bomberUrl,
  pod: podUrl,
  swarmer: swarmerUrl,
  baiter: baiterUrl,
  humanoid: humanoidUrl,
  laser: laserUrl,
  bullet: bulletUrl,
  mine: mineUrl,
  backdrop: backdropUrl,
  terrain: terrainUrl,
};

/** How one sprite frame is drawn (Impl §5.9). */
export interface DrawOptions {
  /** Mirror horizontally. */
  flipX?: boolean;
  /** Radians, clockwise. */
  rotation?: number;
  /** Multiplied into `globalAlpha`. */
  alpha?: number;
  /** Uniform scale, e.g. 0.5 for the HUD's reserve ships. */
  scale?: number;
  /** Stretch the frame horizontally to this logical width. */
  width?: number;
  /** Stretch the frame vertically to this logical height. */
  height?: number;
  /** Logical px skipped from the frame's left edge; the drawn width shrinks by as much. */
  cropLeft?: number;
}

/** The loaded art set (Code §6, Impl §5.9). */
export interface SpriteAtlas {
  /** Loads and size-checks every sprite. Idempotent: every call returns the same promise. */
  load(): Promise<void>;
  /** Draws one frame centered on (x, y), in logical px. Throws on an unknown name or frame. */
  draw(
    ctx: CanvasRenderingContext2D,
    name: SpriteName,
    frame: number,
    x: number,
    y: number,
    opts?: DrawOptions,
  ): void;
}

export function createSpriteAtlas(): SpriteAtlas {
  const images = new Map<SpriteName, HTMLImageElement>();
  let loading: Promise<void> | null = null;

  async function loadOne(name: SpriteName): Promise<void> {
    const { frames, srcW, srcH } = SPRITES[name];
    const image = new Image();
    image.src = URLS[name];
    try {
      await image.decode();
    } catch {
      throw new Error(`sprite ${name}: could not be loaded`);
    }
    const w = frames * srcW;
    if (image.naturalWidth !== w || image.naturalHeight !== srcH)
      throw new Error(
        `sprite ${name}: expected ${String(w)}×${String(srcH)}, got ${String(image.naturalWidth)}×${String(image.naturalHeight)}`,
      );
    images.set(name, image);
  }

  return {
    load() {
      loading ??= Promise.all((Object.keys(SPRITES) as SpriteName[]).map(loadOne)).then(
        () => undefined,
      );
      return loading;
    },
    draw(ctx, name, frame, x, y, opts = {}) {
      const spec = SPRITES[name] as (typeof SPRITES)[SpriteName] | undefined;
      if (!spec) throw new Error(`sprite ${name}: unknown`);
      if (!Number.isInteger(frame) || frame < 0 || frame >= spec.frames)
        throw new Error(`sprite ${name}: no frame ${String(frame)}`);
      const image = images.get(name);
      if (!image) return;

      const { cropLeft = 0, scale = 1, rotation = 0, alpha = 1 } = opts;
      const shown = spec.w - cropLeft;
      if (shown <= 0) return;
      const pxPerUnit = spec.srcW / spec.w;
      const width = opts.width ?? shown;
      const height = opts.height ?? spec.h;
      ctx.save();
      ctx.translate(x, y);
      if (rotation !== 0) ctx.rotate(rotation);
      ctx.scale((opts.flipX ? -1 : 1) * scale, scale);
      ctx.globalAlpha *= alpha;
      ctx.drawImage(
        image,
        (frame * spec.w + cropLeft) * pxPerUnit,
        0,
        shown * pxPerUnit,
        spec.srcH,
        -width / 2,
        -height / 2,
        width,
        height,
      );
      ctx.restore();
    },
  };
}
