/*
System:   camera                    Phase: tick
Job:      Move the camera anchor toward the ship's facing side and place the camera (Design §4.5).
Reads:    world.ship.x, world.ship.facing, world.camera.anchor
Writes:   world.camera.anchor, world.camera.x
Emits:    —
Consumes: —
Guard:    simActive
*/
import { CAMERA, DT } from '../../config/constants';
import { wrapX } from '../../core/math';
import { simActive } from '../../model/queries';
import { cameraTarget } from '../../model/worldOps';
import type { System } from '../../scheduler/system';

export function createCamera(): System {
  return {
    name: 'camera',
    phase: 'tick',
    init() {
      // No platform resources.
    },
    update(state) {
      if (!simActive(state)) return;
      const { camera, ship } = state.world;
      const target = cameraTarget(ship);
      const step = CAMERA.anchorSpeed * DT;
      const gap = target - camera.anchor;
      // Toward the target without overshooting.
      camera.anchor = Math.abs(gap) <= step ? target : camera.anchor + Math.sign(gap) * step;
      camera.x = wrapX(ship.x - camera.anchor);
    },
    dispose() {
      // Nothing to release.
    },
  };
}
