/*
System:   renderDebug               Phase: frame
Job:      Draw the F3 debug overlay: frame and world readouts, and every entity's hitbox outline
          (Impl §10).
Reads:    app.dev.overlay, app.screen, time.tick, time.now, time.alpha, world, fx.shake
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    app.dev.overlay
*/
import { HUD_HEIGHT } from '../../config/constants';
import { PALETTE } from '../../config/palette';
import { lerp } from '../../core/math';
import type { Display } from '../../host/display';
import { cameraXAt, hashWorld, hitboxAt, lerpX, screenX } from '../../model/queries';
import type { World } from '../../model/state/world';
import type { System } from '../../scheduler/system';

const LINE_HEIGHT = 26;
/** The world hash is recomputed every this many world ticks (Impl §10). */
const HASH_INTERVAL = 60;

function worldLines(world: World, hash: string): string[] {
  const { ship } = world;
  const count = (kind: string) => world.enemies.filter((e) => e.kind === kind).length;
  return [
    `WORLD TICK ${String(world.tick)}  PHASE ${world.phase}`,
    `SHIP x ${ship.x.toFixed(0)} y ${ship.y.toFixed(0)} vx ${ship.vx.toFixed(0)} facing ${String(ship.facing)}`,
    `HUM ${String(world.humanoids.length)} LND ${String(count('lander'))} MUT ${String(count('mutant'))} BMB ${String(count('bomber'))} POD ${String(count('pod'))} SWM ${String(count('swarmer'))} BTR ${String(count('baiter'))}`,
    `LASERS ${String(world.lasers.length)} BULLETS ${String(world.bullets.length)} MINES ${String(world.mines.length)}`,
    `HASH ${hash}`,
  ];
}

export function createRenderDebug(): System {
  let display: Display | null = null;
  /** FPS averaged over 1 s windows; null until the first window completes. */
  let fps: number | null = null;
  let windowStart: number | null = null;
  let framesInWindow = 0;
  let hash = '—';
  let hashedWorld: World | null = null;
  let hashedTick = 0;

  /** Outlines the ship's hitbox in red, 1 px, where the ship is drawn (Impl §10). */
  function drawHitboxes(ctx: CanvasRenderingContext2D, world: World, alpha: number) {
    const cam = cameraXAt(world, alpha);
    const { ship } = world;
    const x = screenX(cam, lerpX(ship.prevX, ship.x, alpha));
    const y = HUD_HEIGHT + lerp(ship.prevY, ship.y, alpha);
    const box = hitboxAt('ship', x, y, ship.facing === -1);
    ctx.strokeRect(box.cx - box.w / 2, box.cy - box.h / 2, box.w, box.h);
  }

  return {
    name: 'renderDebug',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
      fps = null;
      windowStart = null;
      framesInWindow = 0;
      hash = '—';
      hashedWorld = null;
    },
    update(state) {
      if (!display || !state.app.dev.overlay) {
        windowStart = null;
        return;
      }
      const { now } = state.time;
      if (windowStart === null) {
        windowStart = now;
        framesInWindow = 0;
      }
      framesInWindow += 1;
      if (now - windowStart >= 1) {
        fps = framesInWindow / (now - windowStart);
        windowStart = now;
        framesInWindow = 0;
      }

      const { world } = state;
      if (world && (world !== hashedWorld || world.tick - hashedTick >= HASH_INTERVAL)) {
        hash = hashWorld(world);
        hashedWorld = world;
        hashedTick = world.tick;
      }

      const ctx = display.scene;
      ctx.save();
      if (world) {
        ctx.save();
        ctx.translate(state.fx.shake.x, state.fx.shake.y);
        ctx.strokeStyle = '#F00';
        ctx.lineWidth = 1;
        drawHitboxes(ctx, world, state.time.alpha);
        ctx.restore();
      }

      const lines = [
        `FPS ${fps === null ? '—' : fps.toFixed(1)}`,
        `TICK ${String(state.time.tick)}`,
        `SCREEN ${state.app.screen}`,
        ...(world ? worldLines(world, hash) : []),
      ];
      ctx.font = '20px monospace';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      const width = Math.max(...lines.map((line) => ctx.measureText(line).width));
      ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
      ctx.fillRect(12, 12, width + 24, 16 + lines.length * LINE_HEIGHT);
      ctx.fillStyle = PALETTE.hudText;
      lines.forEach((line, i) => {
        ctx.fillText(line, 24, 20 + i * LINE_HEIGHT);
      });
      ctx.restore();
    },
    dispose() {
      display = null;
      hashedWorld = null;
    },
  };
}
